import { bytesToHex } from "@noble/hashes/utils";
import { describe, expect, it } from "vitest";
import {
  bidCommitment,
  bidMemo,
  formatZec,
  isCanonical,
  parseZec,
  paymentUri,
  prepareBid,
  roundingOptions,
  verifyReceipt,
} from "./index";

// Generated by `cargo run -p sealforge-core --example vectors` and pinned in
// sealforge-core's receipt tests. The two implementations must agree byte for byte.
const VECTOR = {
  code: "7K3QX9MZ2P",
  refund: "utest1refundexample",
  salt: new Uint8Array(32).fill(1),
  commitment: "76d9fde6644588bafdcfda79e63389a225284a84b51e634ab02a43ad2070592e",
  memo: "SF1:7K3QX9MZ2P:76d9fde6644588bafdcfda79e63389a225284a84b51e634ab02a43ad2070592e:utest1refundexample",
  uri: "zcash:utest1escrowexample?amount=0.42&memo=U0YxOjdLM1FYOU1aMlA6NzZkOWZkZTY2NDQ1ODhiYWZkY2ZkYTc5ZTYzMzg5YTIyNTI4NGE4NGI1MWU2MzRhYjAyYTQzYWQyMDcwNTkyZTp1dGVzdDFyZWZ1bmRleGFtcGxl",
};

describe("matches sealforge-core", () => {
  it("commitment, memo and URI", () => {
    const c = bidCommitment(VECTOR.code, VECTOR.refund, VECTOR.salt);
    expect(bytesToHex(c)).toBe(VECTOR.commitment);
    const memo = bidMemo(VECTOR.code, c, VECTOR.refund);
    expect(memo).toBe(VECTOR.memo);
    expect(paymentUri("utest1escrowexample", 42_000_000n, memo)).toBe(VECTOR.uri);
  });
});

describe("amounts", () => {
  it("formats and parses without floats", () => {
    expect(formatZec(100_000_000n)).toBe("1");
    expect(formatZec(150_000_000n)).toBe("1.5");
    expect(formatZec(1n)).toBe("0.00000001");
    expect(parseZec("1.5")).toBe(150_000_000n);
    expect(parseZec(".25")).toBe(25_000_000n);
    expect(parseZec("0.123456789")).toBeNull();
    expect(parseZec("abc")).toBeNull();
    expect(parseZec("21000001")).toBeNull();
  });

  it("suggests canonical rounding", () => {
    expect(isCanonical(50_000_000n)).toBe(true);
    expect(isCanonical(42_000_000n)).toBe(false);
    expect(roundingOptions(42_000_000n)).toEqual({ lower: 20_000_000n, upper: 50_000_000n });
    expect(roundingOptions(50_000_000n)).toEqual({ lower: 50_000_000n, upper: 50_000_000n });
  });
});

describe("receipts", () => {
  it("prepares a bid with a fresh salt and a self-consistent receipt", () => {
    const a = prepareBid({
      auctionCode: VECTOR.code,
      escrowUa: "utest1escrow",
      amountZat: 50_000_000n,
      refundUa: VECTOR.refund,
    });
    const b = prepareBid({
      auctionCode: VECTOR.code,
      escrowUa: "utest1escrow",
      amountZat: 50_000_000n,
      refundUa: VECTOR.refund,
    });
    expect(a.receipt.salt).not.toBe(b.receipt.salt);
    expect(verifyReceipt(a.receipt)).toBe(true);
    expect(verifyReceipt({ ...a.receipt, refund_ua: "utest1other" })).toBe(false);
    expect(a.uri.startsWith("zcash:utest1escrow?amount=0.5&memo=")).toBe(true);
  });
});
